1	//! Deterministic, graph-owned release roster decisions.
2	//!
3	//! This is deliberately separate from `PublishPlan`: it records the exact
4	//! package/version authority that later intent construction consumes, without
5	//! exposing a mutation route.
6	
7	use callisto_model::{
8	    BumpReason, CommandRunner, CommitSha, Ecosystem, Package, ReleaseDecisionEntry, ReleaseDecisionV1,
9	    ReleaseInclusionReason, ReleasePackageId, Version,
10	};
11	
12	use crate::{DependencyResolver, GraphError, VersionPlan, Workspace};
13	
14	/// Computes one [`ReleasePackageId`] per canonical manifest, ecosystem-qualified
15	/// against `package`'s name.
16	///
17	/// This is the single derivation of release package identity shared by every
18	/// site that computes or verifies release authority: [`derive_release_decision`],
19	/// [`derive_release_commit_decision`], and `release::derive_release_inputs`.
20	/// Per this module's own established lesson (see the doc comment on
21	/// [`derive_release_commit_decision`]), independently reimplementing this
22	/// mapping at each call site is exactly the kind of duplicated derivation
23	/// that drifts -- so it lives here once instead.
24	pub(crate) fn release_package_ids(package: &Package) -> Result<Vec<ReleasePackageId>, GraphError> {
25	    package
26	        .canonical_manifests()
27	        .map(|manifest| ReleasePackageId::new(manifest.ecosystem(), package.id.name()))
28	        .collect::<Result<Vec<_>, _>>()
29	        .map_err(|_error| GraphError::ReleaseIntentStale)
30	}
31	
32	/// Derives the durable roster from a freshly computed version plan.
33	///
34	/// The caller supplies the plan from the same workspace observation; this
35	/// function never inspects `PublishPlan` or a caller-provided release roster.
36	pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
37	    workspace: &Workspace<'_, R, D>,
38	    plan: &VersionPlan,
39	) -> Result<ReleaseDecisionV1, GraphError> {
40	    let mut package_ids = std::collections::BTreeMap::new();
41	    for package in workspace.graph.packages() {
42	        let ids = release_package_ids(package)?;
43	        package_ids.insert(package.id.clone(), ids);
44	    }
45	
46	    let mut entries = Vec::new();
47	    for bump in &plan.bumps {
48	        let ids = package_ids.get(&bump.package).ok_or(GraphError::ReleaseIntentStale)?;
49	        for id in ids {
50	            entries.push(ReleaseDecisionEntry {
51	                package: id.clone(),
52	                target_version: bump.to.clone(),
53	                reasons: vec![reason_from_bump(bump.reason.as_ref(), &package_ids)?],
54	            });
55	        }
56	    }
57	    ReleaseDecisionV1::new(entries).map_err(|_error| GraphError::ReleaseIntentStale)
58	}
59	
60	/// Derives a durable decision for explicit, exact release identities.
61	///
62	/// A linked group is one release unit: selecting any member includes every
63	/// member of that linked group which the version plan selected. All other
64	/// packages remain outside the authority boundary. The caller must pass
65	/// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
66	/// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
67	/// for release authority.
68	pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
69	    workspace: &Workspace<'_, R, D>,
70	    plan: &VersionPlan,
71	    selections: &[ReleasePackageId],
72	) -> Result<ReleaseDecisionV1, GraphError> {
73	    let complete = derive_release_decision(workspace, plan)?;
74	    let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
75	    if selected.len() != selections.len() {
76	        return Err(GraphError::ReleaseIntentStale);
77	    }
78	    if selected
79	        .iter()
80	        .any(|selection| !complete.entries.iter().any(|entry| &entry.package == *selection))
81	    {
82	        return Err(GraphError::ReleaseIntentStale);
83	    }
84	
85	    let linked_groups = complete
86	        .entries
87	        .iter()
88	        .filter(|entry| selected.contains(&entry.package))
89	        .flat_map(|entry| entry.reasons.iter())
90	        .filter_map(|reason| match reason {
91	            ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
92	            _ => None,
93	        })
94	        .collect::<std::collections::BTreeSet<_>>();
95	
96	    let entries = complete
97	        .entries
98	        .into_iter()
99	        .filter(|entry| {
100	            selected.contains(&entry.package)
101	                || entry.reasons.iter().any(|reason| {
102	                    matches!(reason, ReleaseInclusionReason::LinkedGroup { group_id } if linked_groups.contains(group_id))
103	                })
104	        })
105	        .collect();
106	    ReleaseDecisionV1::new(entries).map_err(|_error| GraphError::ReleaseIntentStale)
107	}
108	
109	/// Verifies the release roster a merged release commit claims, against a
110	/// release-decision file committed alongside it at `decision_path`.
111	///
112	/// This is intentionally *not* a second computation of changeset, fixed-group,
113	/// linked-group, cascade, or pre-release-policy inclusion. `plan_version`
114	/// (via [`derive_release_decision`]) already computed that once, correctly,
115	/// when the release PR was generated -- and `callisto version --emit-decision`
116	/// commits its exact output alongside the manifest and changelog edits.
117	/// Re-deriving that policy a second time here, from raw git diffs, is exactly
118	/// the kind of duplicated logic that drifts: an earlier version of this
119	/// function did just that, understood only a direct changeset match, and
120	/// rejected every real release in this repository once a fixed-group cascade
121	/// (a case its reimplementation never learned) touched an unnamed sibling.
122	///
123	/// Instead, this function reads the committed decision back and confirms the
124	/// commit's actual diff matches it exactly -- no more, no less.
125	/// [`ReleaseDecisionV1`]'s own deserializer already rejects a decision whose
126	/// entries don't match its content digest, so a hand-edited or corrupted
127	/// decision file fails before this function's own diff cross-check runs.
128	///
129	/// The caller must check out the exact merge commit in detached HEAD state
130	/// before creating an intent. GitHub-specific PR/approval provenance belongs
131	/// in the workflow boundary; this graph function verifies the local,
132	/// provider-neutral commit delta only.
133	pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
134	    workspace: &Workspace<'_, R, D>,
135	    release_commit: &CommitSha,
136	    decision_path: &std::path::Path,
137	) -> Result<ReleaseDecisionV1, GraphError> {
138	    let head = git_stdout(workspace.runner, &workspace.root, &["rev-parse", "HEAD"])?;
139	    let head = CommitSha::parse(&head).map_err(|_error| GraphError::ReleaseIntentStale)?;
140	    if &head != release_commit {
141	        return Err(GraphError::ReleaseIntentStale);
142	    }
143	
144	    let parent_ref = format!("{}^", release_commit.as_str());
145	    let parent = git_stdout(workspace.runner, &workspace.root, &["rev-parse", &parent_ref])?;
146	    CommitSha::parse(&parent).map_err(|_error| GraphError::ReleaseIntentStale)?;
147	
148	    let changed = git_stdout(
149	        workspace.runner,
150	        &workspace.root,
151	        &[
152	            "diff-tree",
153	            "--no-commit-id",
154	            "--name-status",
155	            "-r",
156	            "--no-renames",
157	            &parent,
158	            release_commit.as_str(),
159	        ],
160	    )?;
161	    let changed = parse_name_status(&changed)?;
162	
163	    // The decision must be freshly authored as part of *this* commit, not a
164	    // stale leftover an earlier release already committed and this one never
165	    // touched -- otherwise a commit that changes nothing real could still
166	    // carry forward a prior, unrelated decision's authority.
167	    let decision_path_str = decision_path.to_string_lossy().replace('\\', "/");
168	    let decision_freshly_written = changed
169	        .iter()
170	        .any(|(status, path)| path == &decision_path_str && matches!(status.as_str(), "A" | "M"));
171	    if !decision_freshly_written {
172	        return Err(GraphError::ReleaseIntentStale);
173	    }
174	
175	    // A cheap, independent sanity check that this commit is a real version
176	    // application and not just a hand-crafted decision file: some real
177	    // changeset was actually consumed. The decision's own entries, not this
178	    // changeset's content, remain the sole authority verified below.
179	    let changeset_dir = workspace.config.changesets_dir.to_string_lossy().replace('\\', "/");
180	    let changeset_prefix = format!("{}/", changeset_dir.trim_end_matches('/'));
181	    let consumed_a_changeset = changed
182	        .iter()
183	        .any(|(status, path)| status == "D" && path.starts_with(&changeset_prefix) && path.ends_with(".md"));
184	    if !consumed_a_changeset {
185	        return Err(GraphError::ReleaseIntentStale);
186	    }
187	
188	    let decision_source = git_file(
189	        workspace.runner,
190	        &workspace.root,
191	        release_commit.as_str(),
192	        &decision_path_str,
193	    )?;
194	    let decision: ReleaseDecisionV1 =
195	        serde_json::from_str(&decision_source).map_err(|_error| GraphError::ReleaseIntentStale)?;
196	    let claimed = decision
197	        .entries
198	        .iter()
199	        .map(|entry| (entry.package.clone(), entry.target_version.clone()))
200	        .collect::<std::collections::BTreeMap<_, _>>();
201	
202	    let changed_paths = changed
203	        .iter()
204	        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
205	        .collect::<std::collections::BTreeSet<_>>();
206	    let mut observed = std::collections::BTreeSet::new();
207	    for package in workspace.graph.packages() {
208	        let package_ids = release_package_ids(package)?;
209	        let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
210	        if package_is_claimed {
211	            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleaseIntentStale)?;
212	            if !changed_paths.contains(changelog.to_string_lossy().as_ref()) {
213	                return Err(GraphError::ReleaseIntentStale);
214	            }
215	        }
216	        for (manifest, id) in package.canonical_manifests().zip(package_ids) {
217	            let path = manifest.path.to_string_lossy();
218	            let before = manifest_version_at(workspace.runner, &workspace.root, &parent, &path, manifest.ecosystem())?;
219	            let after = manifest_version_at(
220	                workspace.runner,
221	                &workspace.root,
222	                release_commit.as_str(),
223	                &path,
224	                manifest.ecosystem(),
225	            )?;
226	            let changed_version = before != after;
227	            match claimed.get(&id) {
228	                Some(target_version) => {
229	                    if !changed_version || &after != target_version || !changed_paths.contains(path.as_ref()) {
230	                        return Err(GraphError::ReleaseIntentStale);
231	                    }
232	                    observed.insert(id);
233	                }
234	                None => {
235	                    if changed_version {
236	                        // A changed version the committed decision never
237	                        // claimed is not this commit's authority -- fail
238	                        // closed rather than trust a partial match.
239	                        return Err(GraphError::ReleaseIntentStale);
240	                    }
241	                }
242	            }
243	        }
244	    }
245	    if observed.len() != claimed.len() {
246	        return Err(GraphError::ReleaseIntentStale);
247	    }
248	
249	    Ok(decision)
250	}
251	
252	fn git_stdout<R: CommandRunner>(runner: &R, root: &std::path::Path, args: &[&str]) -> Result<String, GraphError> {
253	    let output = runner.run("git", args, root)?;
254	    if !output.success() {
255	        return Err(GraphError::ReleaseIntentStale);
256	    }
257	    Ok(output.stdout_trimmed().to_string())
258	}
259	
260	fn parse_name_status(output: &str) -> Result<Vec<(String, String)>, GraphError> {
261	    output
262	        .lines()
263	        .map(|line| {
264	            let (status, path) = line.split_once('\t').ok_or(GraphError::ReleaseIntentStale)?;
265	            if !matches!(status, "A" | "M" | "D") || path.is_empty() || path.contains('\0') {
266	                return Err(GraphError::ReleaseIntentStale);
267	            }
268	            Ok((status.to_string(), path.to_string()))
269	        })
270	        .collect()
271	}
272	
273	fn git_file<R: CommandRunner>(
274	    runner: &R,
275	    root: &std::path::Path,
276	    commit: &str,
277	    path: &str,
278	) -> Result<String, GraphError> {
279	    let object = format!("{commit}:{path}");
280	    git_stdout(runner, root, &["show", &object])
281	}
282	
283	fn manifest_version_at<R: CommandRunner>(
284	    runner: &R,
285	    root: &std::path::Path,
286	    commit: &str,
287	    path: &str,
288	    ecosystem: Ecosystem,
289	) -> Result<Version, GraphError> {
290	    let source = git_file(runner, root, commit, path)?;
291	    let format = ecosystem
292	        .canonical_manifest_format()
293	        .ok_or(GraphError::ReleaseIntentStale)?;
294	    // A malformed blob, a version-less manifest (e.g. a Cargo workspace
295	    // root with no [package] table, or a `dynamic = ["version"]` PEP 621
296	    // package), or a Cargo `version.workspace = true` inheritance (which
297	    // `read_identity` deliberately never resolves, having no workspace
298	    // context for a historical git blob) all fail closed here rather than
299	    // panicking or fabricating a version.
300	    let version = callisto_manifests::read_identity(format, &source, std::path::Path::new(path))
301	        .ok()
302	        .and_then(|identity| match identity.version {
303	            Some(callisto_manifests::VersionSource::Literal(v)) => Some(v),
304	            _ => None,
305	        })
306	        .ok_or(GraphError::ReleaseIntentStale)?;
307	    Version::parse(&version, ecosystem.version_grammar()).map_err(|_error| GraphError::ReleaseIntentStale)
308	}
309	
310	fn reason_from_bump(
311	    reason: Option<&BumpReason>,
312	    package_ids: &std::collections::BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
313	) -> Result<ReleaseInclusionReason, GraphError> {
314	    match reason {
315	        Some(BumpReason::Changeset { .. }) | None => Ok(ReleaseInclusionReason::Changeset),
316	        Some(BumpReason::Inference { .. }) => Ok(ReleaseInclusionReason::Inference),
317	        Some(BumpReason::LinkedGroupUnion { group }) => Ok(ReleaseInclusionReason::LinkedGroup {
318	            group_id: group.to_string(),
319	        }),
320	        Some(BumpReason::FixedGroupUnion { group } | BumpReason::NewGroupMember { group }) => {
321	            Ok(ReleaseInclusionReason::FixedGroup {
322	                group_id: group.to_string(),
323	            })
324	        }
325	        Some(BumpReason::PreRelease { tag }) => Ok(ReleaseInclusionReason::PreReleasePolicy { policy_id: tag.clone() }),
326	        Some(BumpReason::Cascade { via, dep_kind, .. }) => {
327	            let source = package_ids
328	                .get(via)
329	                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
330	                .ok_or(GraphError::ReleaseIntentStale)?;
331	            Ok(ReleaseInclusionReason::Cascade {
332	                from: source,
333	                edge_kind: format!("{dep_kind:?}"),
334	            })
335	        }
336	        Some(BumpReason::PeerEscalation { via, .. }) => {
337	            let source = package_ids
338	                .get(via)
339	                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
340	                .ok_or(GraphError::ReleaseIntentStale)?;
341	            Ok(ReleaseInclusionReason::Cascade {
342	                from: source,
343	                edge_kind: "peer".to_string(),
344	            })
345	        }
346	        Some(_) => Err(GraphError::ReleaseIntentStale),
347	    }
348	}
