356	    #[test]
357	    fn decision_is_canonical_and_ecosystem_qualified() {
358	        let cargo = ReleasePackageId::new(Ecosystem::Cargo, "demo").unwrap();
359	        let npm = ReleasePackageId::new(Ecosystem::Npm, "demo").unwrap();
360	        let first = ReleaseDecisionV1::new(vec![
361	            ReleaseDecisionEntry {
362	                package: npm,
363	                target_version: Version::semver(1, 0, 0),
364	                reasons: vec![ReleaseInclusionReason::ExplicitSelection],
365	            },
366	            ReleaseDecisionEntry {
367	                package: cargo,
368	                target_version: Version::semver(1, 0, 0),
369	                reasons: vec![ReleaseInclusionReason::ExplicitSelection],
370	            },
371	        ])
372	        .unwrap();
373	        assert_eq!(first.entries[0].package.to_string(), "cargo/demo");
374	        assert_ne!(first.entries[0].package, first.entries[1].package);
375	    }
