377	    #[test]
378	    fn release_commit_delta_parser_accepts_only_unambiguous_path_statuses() {
379	        assert_eq!(
380	            parse_name_status("M\tCargo.toml\nD\t.changeset/release.md\n").unwrap(),
381	            vec![
382	                ("M".to_string(), "Cargo.toml".to_string()),
383	                ("D".to_string(), ".changeset/release.md".to_string()),
384	            ]
385	        );
386	        assert!(parse_name_status("R100\told\tnew\n").is_err());
387	        assert!(parse_name_status("M Cargo.toml\n").is_err());
