421	            let result = manifest_version_at(&runner, std::path::Path::new("."), "deadbeef", "Cargo.toml", *ecosystem);
422	            assert!(
423	                matches!(result, Err(GraphError::ReleaseIntentStale)),
424	                "expected a clean ReleaseIntentStale rejection (not a panic) for {ecosystem:?}, got {result:?}"
425	            );
426	        }
427	    }
