129	/// Returns the leading run of ASCII digits in `s`, stopping at the first
130	/// non-digit character (or the end of the string). Used to strip anything
131	/// `semver` would otherwise interpret as pre-release/build metadata (a
132	/// hyphen or plus) or a non-numeric trailing suffix, since a git version's
133	/// own reported string was never intended to carry semver's meaning for
134	/// those -- see [`check_git_version`]'s doc comment.
135	fn leading_digits(s: &str) -> &str {
136	    let end = s.find(|c: char| !c.is_ascii_digit()).unwrap_or(s.len());
137	    &s[..end]
138	}
