140	/// Validates git version against the [`REQUIRED_GIT`] floor.
141	///
142	/// `reported` is raw `git --version` output (e.g. `"git version 2.39.5"`,
143	/// `"...2.39.5.windows.1"` on Windows, `"...2.39.5-rc1"` for a pre-release).
144	/// Only the leading `major.minor.patch` triple is parsed, each component
145	/// truncated at its first non-digit char (`5-rc1` -> `5`) before reaching
146	/// `semver`: an unstripped hyphenated suffix would make `semver::VersionReq`
147	/// exclude it from the `>=2.20` floor entirely, since semver reqs never
148	/// match a pre-release unless the requirement itself carries a matching
149	/// tag -- irrelevant to a real git build tag. Extra dot-separated
150	/// components (`.windows.1`) are ignored; a missing minor/patch defaults
151	/// to `0`.
152	///
153	/// Comparison itself is delegated to [`semver::VersionReq`] parsing
154	/// [`REQUIRED_GIT`], so the floor lives in one place, not a hand-maintained
155	/// duplicate that could drift from the error message's constant.
156	pub fn check_git_version(reported: &str) -> Result<(), CommandError> {
157	    let incompatible = || CommandError::IncompatibleVersion {
158	        program: "git".to_string(),
159	        found: reported.to_string(),
160	        required: REQUIRED_GIT.to_string(),
161	    };
162	
163	    let version_str = reported.trim();
164	    let digits = version_str
165	        .split_whitespace()
166	        .find(|word| word.chars().next().is_some_and(|c| c.is_ascii_digit()))
167	        .unwrap_or(version_str);
168	
169	    let mut parts = digits.splitn(4, '.').take(3);
170	    let major = leading_digits(parts.next().unwrap_or("0"));
171	    let minor = leading_digits(parts.next().unwrap_or("0"));
172	    let patch = leading_digits(parts.next().unwrap_or("0"));
173	    let core = format!("{major}.{minor}.{patch}");
174	
175	    let version = semver::Version::parse(&core).map_err(|_parse_err| incompatible())?;
176	    let required = semver::VersionReq::parse(REQUIRED_GIT).map_err(|_parse_err| incompatible())?;
177	
178	    if required.matches(&version) {
179	        Ok(())
180	    } else {
181	        Err(incompatible())
182	    }
183	}
