341	    /// Regression test for a hung-descendant deadlock: killing the direct
342	    /// child does not close pipe fds inherited by a grandchild process that
343	    /// outlives it. The direct child (`sh`) exits almost immediately, but a
344	    /// backgrounded grandchild (`sleep 30`) keeps stderr open well past
345	    /// that. If the reader threads are joined unconditionally, this call
346	    /// hangs for ~30s regardless of the requested timeout. The fix bounds
347	    /// how long we wait on the reader threads so the call always returns
348	    /// promptly.
349	    #[test]
350	    fn run_with_timeout_bounds_reader_join_when_descendant_holds_pipe_open() {
351	        let runner = CliCommandRunner;
352	        let start = Instant::now();
353	        let result = runner.run_with_timeout(
354	            "sh",
355	            &["-c", "sleep 30 >&2 & exit 0"],
356	            std::path::Path::new("."),
357	            Duration::from_secs(2),
358	        );
359	        let elapsed = start.elapsed();
360	        assert!(
361	            elapsed < Duration::from_secs(6),
362	            "run_with_timeout must not block on a descendant process holding \
363	             stdio pipes open; took {elapsed:?}, result: {result:?}"
364	        );
365	        assert!(
366	            result.is_ok(),
367	            "expected Ok despite a lingering descendant holding the pipe open, got: {result:?}"
368	        );
369	    }
